int a = 10;
int b = a++;
System.out.println(a);
System.out.println(b);

int a = 10;
int b = ++a;
System.out.println(a);
System.out.println(b);

int a = 10;
int b = a--;
System.out.println(a);
System.out.println(b);

int a = 10;
int b = --a;
System.out.println(a);
System.out.println(b);

boolean a = true;
boolean b = !a;
System.out.println(b);

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int age = scan.nextInt();
        int result = age >= 18 ? 1 : 0;
        System.out.println(result);
    }
}

